// Regle des polices de l'edition francaise (police choisie selon le texte, comme Sierra), regles propres a certains textes
// et fenetres elargies (Finances, Culture, messages, boutons des didacticiels), pour la compilation anglaise 2.1.4.0.
// Les routines vont en fin de .rdata (0x5E73C0) : au-dela de sa taille virtuelle, mais dans sa partie brute du fichier.
// Reglages :
//   Règle : 1>10+3 2>14+3 3>13+3 4>14+3 5>8+3 6>1+7 9>12+3
//   Texte 31/0 : police 6>1 dx 0 dy 7
//   Texte 13/5 : police inchangée dx -25 dy 0
//   Texte 287/2 : police inchangée dx -25 dy 0
//   Texte 61/1-12 : police 3>13 dx 0 dy 3
//   Texte 174/* : police 1>10 dx 0 dy 3
//   Fenêtre finances : largeur +4 dx -43 texte 0
//   Fenêtre culture : largeur +4 dx 0 texte 0
//   Fenêtre didacticiels : largeur +1 dx -5 texte -16
//   Fenêtre messages : largeur +5 dx 40 texte -40
using System;
using System.Collections.Generic;

public static class ReglePolices
{
    // Nom du premier endroit qui a empeche la regle des polices (dernier Build), ou null.
    public static string Skipped;

    // Tout ou rien, car un crochet sans ses routines planterait : liste vide si un autre patch a touche un endroit requis.
    public static List<Site> Build(byte[] exe)
    {
        Skipped = null;
        List<Site> s = Sites(exe, new Pe(exe));
        foreach (Site x in s)
            if (x.Required && x.StateIn(exe) == SiteState.Other) { Skipped = x.Name; return new List<Site>(); }
        return s;
    }

    static List<Site> Sites(byte[] exe, Pe pe)
    {
        List<Site> s = new List<Site>();
        foreach (object[] e in Table)
        {
            Site x = new Site((string)e[4], pe.Off((uint)e[0]), FromHex((string)e[2]), FromHex((string)e[3]));
            x.Required = (bool)e[1];
            s.Add(x);
        }
        // en-tete de .rdata : taille virtuelle portee a toute la partie brute, execution et ecriture permises
        // (les routines ecrivent dans leurs variables)
        int i = pe.Names.IndexOf(".rdata");
        if (i < 0) throw new Exception(L.T("section .rdata introuvable", ".rdata section not found"));
        uint[] r = pe.Secs[i];
        int hdr = (int)r[5];
        uint vs = BitConverter.ToUInt32(exe, hdr + 8), fl = BitConverter.ToUInt32(exe, hdr + 36);
        s.Add(new Site("en-tête .rdata (taille)", hdr + 8, BitConverter.GetBytes(vs), BitConverter.GetBytes(Math.Max(vs, r[3]))));
        s.Add(new Site("en-tête .rdata (attributs)", hdr + 36, BitConverter.GetBytes(fl), BitConverter.GetBytes(fl | 0xA0000000u)));
        return s;
    }

    static byte[] FromHex(string h)
    {
        byte[] b = new byte[h.Length / 2];
        for (int i = 0; i < b.Length; i++) b[i] = Convert.ToByte(h.Substring(2 * i, 2), 16);
        return b;
    }

    // Endroits : adresse, indispensable, octets d'origine, octets du patch, nom.

    static readonly object[][] Table = {
        new object[] { 0x005E73C0u, true, "", "", "règle des polices : routines ajoutées" },
        new object[] { 0x00508813u, true, "E8E887EFFF", "E818F10D00", "règle des polices : textes" },
        new object[] { 0x00508682u, true, "E87989EFFF", "E8C9F20D00", "règle des polices : textes centrés" },
        new object[] { 0x00508807u, true, "7412", "9090", "règles par texte : crochet des textes pour chaque texte" },
        new object[] { 0x00508676u, true, "7412", "9090", "règles par texte : crochet des textes centrés pour chaque texte" },
        new object[] { 0x005090A0u, true, "51538B5C2414", "E9CBE80D0090", "règles par texte : paragraphes" },
        new object[] { 0x005094C0u, true, "568B742418", "E9CBE40D00", "règles par texte : textes alignés à droite" },
        new object[] { 0x004F32F0u, true, "0FBF80CC3CF1006A00", "E97B410F0090909090", "règle des polices : titre des messages" },
        new object[] { 0x005B5AF0u, true, "8A542410A120C82B01", "E9AB19030090909090", "règle des polices : boutons 01" },
        new object[] { 0x005B5E10u, true, "8A4C2410A120C82B01", "E9CB16030090909090", "règle des polices : boutons 02" },
        new object[] { 0x005B5FA0u, true, "A120C82B01", "E97B150300", "règle des polices : boutons 03" },
        new object[] { 0x005B6260u, true, "A120C82B01", "E9FB120300", "règle des polices : boutons 04" },
        new object[] { 0x005B6350u, true, "A120C82B01", "E94B120300", "règle des polices : boutons 05" },
        new object[] { 0x005B65C0u, true, "8A44240C84C0", "E91B10030090", "règle des polices : boutons 06" },
        new object[] { 0x005B6690u, true, "A144B5FE00", "E98B0F0300", "règle des polices : boutons 07" },
        new object[] { 0x005B6730u, true, "8A4424108B0D20C82B01", "E92B0F03009090909090", "règle des polices : boutons 08" },
        new object[] { 0x005B6830u, true, "A120C82B01", "E97B0E0300", "règle des polices : boutons 09" },
        new object[] { 0x005B69D0u, true, "566A016A01", "E91B0D0300", "règle des polices : boutons 10" },
        new object[] { 0x005B6AE0u, true, "5153555657", "E94B0C0300", "règle des polices : boutons 11" },
        new object[] { 0x00598162u, false, "83F801", "83F80A", "police « Gros carré » (éditeur)" },
        new object[] { 0x0059816Cu, false, "83C008", "83C050", "police « Gros carré » (éditeur, rang)" },
        new object[] { 0x0059520Au, true, "C705D4FE0D0121000000", "C705D4FE0D0125000000", "fenêtre finances : largeur" },
