        new object[] { 0x0065C348u, true, "", "", "boutons des didacticiels (gauche) : rectangles" },
        new object[] { 0x005BE9BAu, true, "6ABF", "6AAF", "boutons des didacticiels (gauche) : texte" },
        new object[] { 0x0065C428u, true, "", "", "boutons des didacticiels (droite) : rectangles" },
        new object[] { 0x005BEA36u, true, "6ABD", "6AAD", "boutons des didacticiels (droite) : texte" },
    };
}
